SELECT inventory.last_restock, inventory.quantity, store_sales.store_id, store_sales.sale_date, store_sales.units, DATEDIFF(CURRENT_DATE(), store_sales.sale_date) AS days_since_sale_date FROM inventory INNER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.sale_date >= '2024-09-01' AND store_sales.sale_date < '2024-10-01' ORDER BY quantity DESC;
